add('P1850','当前教室是否申请的期望 DP',
    'Floyd 求教室间最短路，dp[天数][申请次数][当天是否申请] 维护最小期望路程。相邻两天按各自成功或失败的概率组合四种距离转移。',
    '每天是否申请必须预先决定，不能看到结果再改变后续计划。申请结果相互独立，所以给定相邻两天是否申请后，它们之间的期望距离固定，可作为 DP 边权。\n\n某天不申请时原教室概率一；申请时新教室概率 p、原教室概率 1−p。前后两天共有最多四种组合，把最短距离乘概率后相加。dp 只需保留上一天是否申请，便足以确定本次转移代价。\n\n从第一天开始，没有之前的路程，不申请状态费用零，若有申请额度，申请状态也为零但用掉一次额度。逐日转移，最后对不超过 m 次的全部状态取最小。先对道路做 Floyd，重边取最小值。',
    '时间 O(v³+nm)，空间 O(v²+m)。','申请决定不能依据随机结果；第一天也可申请；最多 m 次而非恰好。',r'''
int n,m,v,e;cin>>n>>m>>v>>e;vector<int>c(n),d(n);vector<long double>p(n);for(int&x:c){cin>>x;x--;}for(int&x:d){cin>>x;x--;}for(auto&x:p)cin>>x;const long double INF=1e80L;vector<vector<long double>>dist(v,vector<long double>(v,INF));for(int i=0;i<v;i++)dist[i][i]=0;while(e--){int a,b;long double w;cin>>a>>b>>w;a--;b--;dist[a][b]=dist[b][a]=min(dist[a][b],w);}for(int k=0;k<v;k++)for(int i=0;i<v;i++)for(int j=0;j<v;j++)dist[i][j]=min(dist[i][j],dist[i][k]+dist[k][j]);vector<array<long double,2>>dp(m+1,{INF,INF});dp[0][0]=0;if(m)dp[1][1]=0;for(int day=1;day<n;day++){long double cost[2][2]{};for(int before=0;before<2;before++)for(int now=0;now<2;now++)for(int a=0;a<2;a++)for(int b=0;b<2;b++){long double pa=before?(a?p[day-1]:1-p[day-1]):(a?0:1),pb=now?(b?p[day]:1-p[day]):(b?0:1);cost[before][now]+=pa*pb*dist[a?d[day-1]:c[day-1]][b?d[day]:c[day]];}vector<array<long double,2>>next(m+1,{INF,INF});for(int used=0;used<=m;used++)for(int before=0;before<2;before++)for(int now=0;now<2;now++)if(used+now<=m)next[used+now][now]=min(next[used+now][now],dp[used][before]+cost[before][now]);dp.swap(next);}long double ans=INF;for(auto state:dp)ans=min({ans,state[0],state[1]});cout<<fixed<<setprecision(2)<<ans<<'\n';
''')

add('P4284','两遍树形 DP 求每点未通电概率',
    '先求每个子树都无法使根点通电的概率，再从根向下传递来自子树外的断电概率。点未通电概率是两者乘积，期望通电数为 Σ(1−未通电概率)。',
    '边能传电与否、每点自身通电事件均独立。设 down[u] 为只考虑 u 子树时 u 不通电的概率，child v 这一路不能带电的概率为 (1−edgeP)+edgeP·down[v]。因此 down[u]=(1−自身概率) 乘全部孩子的这一因子。\n\n再令 outside[u] 表示来自父侧的一切无法使 u 通电的概率，根为一。要向孩子 v 传递，先算 u 在去掉 v 子树后不通电的概率，即 outside[u]·(1−自身概率)·其余孩子因子；通过 u—v 边得到 outside[v]=(1−edgeP)+edgeP·该概率。\n\n使用前后缀乘积排除一个孩子，不能用总乘积除以它的因子，因为因子可能为零。最后 down[u]outside[u] 为完全断电概率，利用期望线性性求和，不需要计算各点同时通电的联合分布。',
    '时间 O(n)，空间 O(n)。','输入百分数除以一百；零因子用前后缀乘积；答案保留六位小数。',r'''
int n;cin>>n;vector<vector<pair<int,long double>>>g(n);for(int i=1;i<n;i++){int a,b;long double p;cin>>a>>b>>p;a--;b--;p/=100;g[a].push_back({b,p});g[b].push_back({a,p});}vector<long double>self(n),down(n),outside(n,1),edge(n);for(auto&x:self){cin>>x;x/=100;}vector<int>parent(n,-1),order={0};parent[0]=0;for(int i=0;i<n;i++)for(auto[u,p]:g[order[i]])if(parent[u]<0){parent[u]=order[i];edge[u]=p;order.push_back(u);}for(int i=n-1;i>=0;i--){int v=order[i];down[v]=1-self[v];for(auto[u,p]:g[v])if(parent[u]==v)down[v]*=1-p+p*down[u];}long double ans=0;for(int v:order){ans+=1-down[v]*outside[v];vector<int>children;vector<long double>factors;for(auto[u,p]:g[v])if(parent[u]==v){children.push_back(u);factors.push_back(1-p+p*down[u]);}int z=children.size();vector<long double>prefix(z+1,1),suffix(z+1,1);for(int i=0;i<z;i++)prefix[i+1]=prefix[i]*factors[i];for(int i=z-1;i>=0;i--)suffix[i]=suffix[i+1]*factors[i];for(int i=0;i<z;i++){int u=children[i];long double no=outside[v]*(1-self[v])*prefix[i]*suffix[i+1];outside[u]=1-edge[u]+edge[u]*no;}}cout<<fixed<<setprecision(6)<<ans<<'\n';
''')

add('P4683','遍历单词 Trie，最长路径留到最后',
    '所有单词组成 Trie。每条非最终路径边至少走去回两次，最终停留路径只需走一次，所以选择最长根路径最后访问。遇到单词结点输出打印操作。',
    '输入所有词必须被打印，Trie 中的每条边都至少向下经过一次。若最终停在深度 L 的结点，只有根到该结点的 L 条边可以不返回，其余边还必须向上走一次。因此操作数至少为 2·边数−L+词数，选择最深单词可使下界最小。\n\nDFS 遍历 Trie，进入孩子时输出字母、回到父亲时输出减号，单词结点输出 P。每个结点把通向最深后代的孩子留到最后，这让整体最后打印的词具有最大深度。\n\n遍历结束后去掉尾部所有减号，恰好省掉最终根路径的返回操作，达到下界。单词最长二十，递归深度安全；代码输出的操作序列用独立模拟器检查打印词集合和最小操作数。',
    '设总字符数为 S，时间 O(26S)，空间 O(S)。','最终不要求清空；最长分支最后走；P 也是一次操作。',r'''
int n;cin>>n;struct Node{array<int,26>next{};bool terminal=false;int height=0;};vector<Node>trie(1);while(n--){string s;cin>>s;int v=0;for(char c:s){int x=c-'a';if(!trie[v].next[x]){trie[v].next[x]=trie.size();trie.emplace_back();}v=trie[v].next[x];}trie[v].terminal=true;}for(int v=(int)trie.size()-1;v>=0;v--)for(int u:trie[v].next)if(u)trie[v].height=max(trie[v].height,trie[u].height+1);string ops;function<void(int)>dfs=[&](int v){if(trie[v].terminal)ops+='P';int last=-1;for(int c=0;c<26;c++)if(trie[v].next[c]&&(last<0||trie[trie[v].next[c]].height>trie[trie[v].next[last]].height))last=c;for(int c=0;c<26;c++)if(trie[v].next[c]&&c!=last){ops+=char('a'+c);dfs(trie[v].next[c]);ops+='-';}if(last>=0){ops+=char('a'+last);dfs(trie[v].next[last]);ops+='-';}};dfs(0);while(!ops.empty()&&ops.back()=='-')ops.pop_back();cout<<ops.size()<<'\n';for(char c:ops)cout<<c<<'\n';
''',checker='type-printer')

add('P6088','边标签字典序区间与持久化计数树',
    '所有以 S 为前缀的标签在字典序中连续。将标签排序离散化，每个树点保存根路径标签频次的持久化线段树，查询以 u、v 两根减去两份 LCA 根得到路径频次。',
    '小写字符串以 S 为前缀，当且仅当它落在字典序区间 [S,S+\'{\')，其中左花括号排在 z 之后。二分就能把前缀条件转换成标签排名区间。\n\n设 version[u] 保存从全树根到 u 的边标签计数。从父亲版本复制，并在当前父边标签处加一，只需复制线段树根到叶的一条路径。边权路径计数为 version[u]+version[v]−2version[lca]；LCA 的父边不在路径中，正好被两次消掉。\n\n在三个版本上同时查询排名区间即可。字符串在边上，不是点上，所以不能再补上 LCA 标签。u=v 时自然为零，只有一个顶点的树也无需建立标签树。',
    '预处理 O(n log n)，每问 O(log n+|S| log n)，空间 O(n log n)。','标签是边权；前缀上界用 S 加左花括号；LCA 版本减两次。',r'''
int n;cin>>n;vector<vector<int>>g(n);vector<tuple<int,int,string>>edges;vector<string>words;for(int i=1;i<n;i++){int a,b;string s;cin>>a>>b>>s;a--;b--;g[a].push_back(b);g[b].push_back(a);edges.push_back({a,b,s});words.push_back(s);}sort(words.begin(),words.end());words.erase(unique(words.begin(),words.end()),words.end());HLD tree(g);vector<int>label(n),root(n);for(auto[a,b,s]:edges){if(tree.parent[a]==b)swap(a,b);label[b]=lower_bound(words.begin(),words.end(),s)-words.begin();}struct Node{int l=0,r=0,count=0;};vector<Node>pool(1);pool.reserve(20LL*n+1);function<int(int,int,int,int)>insert=[&](int old,int l,int r,int x){int cur=pool.size();pool.push_back(pool[old]);pool[cur].count++;if(l<r){int mid=(l+r)/2;if(x<=mid)pool[cur].l=insert(pool[old].l,l,mid,x);else pool[cur].r=insert(pool[old].r,mid+1,r,x);}return cur;};int M=words.size();for(int u:tree.order)if(u)root[u]=insert(root[tree.parent[u]],0,M-1,label[u]);function<int(int,int,int,int,int,int,int)>query=[&](int a,int b,int c,int l,int r,int L,int R){if(L<=l&&r<=R)return pool[a].count+pool[b].count-2*pool[c].count;int mid=(l+r)/2,ans=0;if(L<=mid)ans+=query(pool[a].l,pool[b].l,pool[c].l,l,mid,L,R);if(R>mid)ans+=query(pool[a].r,pool[b].r,pool[c].r,mid+1,r,L,R);return ans;};int q;cin>>q;while(q--){int a,b;string s;cin>>a>>b>>s;a--;b--;int L=lower_bound(words.begin(),words.end(),s)-words.begin(),R=lower_bound(words.begin(),words.end(),s+'{')-words.begin()-1;if(L>R)cout<<0<<'\n';else cout<<query(root[a],root[b],root[tree.lca(a,b)],0,M-1,L,R)<<'\n';}
''',HLD)

add('UVA11019','模式行 AC 匹配后按列做 KMP',
    '把每个不同模式行映射为一个编号，用 AC 自动机扫描正文各行，得到每个结束列匹配到的模式行编号。再在每列竖直方向对编号序列做 KMP，完整匹配一次就是一个子矩阵。',
    '二维匹配可以先固定横向宽度：正文某行某个结束列的长度 Y 子串，若等于某个模式行，就记它的编号。重复模式行必须使用同一个编号，因为它们的内容没有区别。\n\n将模式各行加入 AC 自动机，一次扫描每个正文行即可得到所有列的行编号；所有模式行等长，所以一个位置最多匹配一种不同模式行，不必遍历很多输出链。字符未命中任何模式行时记为 −1。\n\n对每个结束列，沿行方向读取这些编号，使用 KMP 匹配模式行编号序列。命中 X 个编号就找到一个高 X、宽 Y 的模式子矩阵，之后按失配函数回退以支持重叠。自动机使用字节字符表，避免擅自限制原题未规定的字母范围。',
    '字节字符集大小固定 256，时间 O(NM+256XY)，空间 O(NM+256XY+M)。','相同模式行共用编号；每列独立保存竖向匹配状态；重叠出现也计数。',r'''
int T;cin>>T;while(T--){int N,M;cin>>N>>M;vector<string>text(N);for(auto&s:text)cin>>s;int X,Y;cin>>X>>Y;struct Node{array<int,256>next{};int fail=0,id=-1;};vector<Node>ac(1);vector<int>pattern(X);int labels=0;for(int i=0;i<X;i++){string s;cin>>s;int v=0;for(unsigned char c:s){if(!ac[v].next[c]){ac[v].next[c]=ac.size();ac.emplace_back();}v=ac[v].next[c];}if(ac[v].id<0)ac[v].id=labels++;pattern[i]=ac[v].id;}queue<int>q;for(int c=0;c<256;c++)if(ac[0].next[c])q.push(ac[0].next[c]);while(!q.empty()){int v=q.front();q.pop();for(int c=0;c<256;c++){int u=ac[v].next[c];if(u){ac[u].fail=ac[ac[v].fail].next[c];q.push(u);}else ac[v].next[c]=ac[ac[v].fail].next[c];}}vector<int>pi(X);for(int i=1;i<X;i++){int j=pi[i-1];while(j&&pattern[i]!=pattern[j])j=pi[j-1];if(pattern[i]==pattern[j])j++;pi[i]=j;}vector<int>vertical(M);long long ans=0;for(auto&s:text){int v=0;for(int j=0;j<M;j++){v=ac[v].next[(unsigned char)s[j]];int id=ac[v].id,k=vertical[j];while(k&&id!=pattern[k])k=pi[k-1];if(id==pattern[k])k++;if(k==X){ans++;k=pi[k-1];}vertical[j]=k;}}cout<<ans<<'\n';}
''')
